/** Immutable identity generated by the protected Worker release from one
 * Repository Variable. It is not an MCP caller input or a live remote setting.
 */
export type WorkflowGitHubExecutor = Readonly<{
  repository:string;
  repositoryId:number;
  ciWorkflowId:number;
}>;

const NAME=/^[A-Za-z0-9_.-]+\/[A-Za-z0-9_.-]+$/;
export function readWorkflowGitHubExecutor(raw:unknown):WorkflowGitHubExecutor|null {
  if(typeof raw!=='string'||!raw||raw.length>512)return null;
  let entry:unknown;
  try{entry=JSON.parse(raw);}catch{return null;}
  if(!entry||typeof entry!=='object'||Array.isArray(entry))return null;
  const data=entry as Record<string,unknown>;
  if(Object.keys(data).sort().join(',')!=='ciWorkflowId,repository,repositoryId'||
     typeof data.repository!=='string'||data.repository.length>201||
     !NAME.test(data.repository)||data.repository.includes('..')||
     data.repository.split('/').some(x=>x.startsWith('.')||x.endsWith('.'))||
     !Number.isSafeInteger(data.repositoryId)||(data.repositoryId as number)<=0||
     !Number.isSafeInteger(data.ciWorkflowId)||(data.ciWorkflowId as number)<=0)return null;
  return {repository:data.repository,repositoryId:data.repositoryId as number,
    ciWorkflowId:data.ciWorkflowId as number};
}

export function isWellFormedWorkflowGitHubRepository(value:unknown):value is string {
  return typeof value==='string' && value.length<=201 && NAME.test(value) &&
    !value.includes('..') &&
    value.split('/').every(x=>!x.startsWith('.')&&!x.endsWith('.'));
}

export function isCurrentWorkflowGitHubAction(
  identity:Pick<WorkflowGitHubExecutor,'repository'|'repositoryId'>|null,
  action:{repository:unknown;repositoryId:unknown}|null|undefined,
):boolean {
  return !!identity&&!!action&&identity.repository===action.repository&&
    identity.repositoryId===action.repositoryId;
}
